#!/usr/bin/env bash\nset -e\n\n# Build the Docker image (quietly)\ndocker build -t nightly-quote-bot-test . > /dev/null\n\n# Run container with a known index and capture its output\noutput=$(docker run --rm -e QUOTE_INDEX=2 nightly-quote-bot-test)\n\nexpected="In the middle of difficulty lies opportunity... and maybe a snack."\n\nif [ "$output" = "$expected" ]; then\n  echo "Test passed"\n  exit 0\nelse\n  echo "Test failed: expected '$expected' but got '$output'"\n  exit 1\nfi\n
